const ts1 = 1788228000.0;
const ts2 = 1788269400.0;

const gap = ts2 - ts1;
console.log('Timestamp 1:', ts1);
console.log('Timestamp 2:', ts2);
console.log('Time gap:', gap, 'seconds');
console.log('Time gap:', gap / 3600, 'hours');
console.log('Time gap:', gap / 60, 'minutes');

const newTs = ts1 + gap;
console.log('\nNew timestamp (ts1 + gap):', newTs);

const dt1 = new Date(ts1 * 1000);
const dt2 = new Date(ts2 * 1000);
const dtNew = new Date(newTs * 1000);
console.log('\nTimestamp 1 readable:', dt1.toUTCString());
console.log('Timestamp 2 readable:', dt2.toUTCString());
console.log('New timestamp readable:', dtNew.toUTCString());
"
